 async function api(action,payload={}){
  const token=await PC_SITE_CLOUD.accessToken();if(!token)throw Error('ابتدا با حساب ابری خود وارد فروشگاه شوید.');
  const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),25000);
  busy++;connection();
  try{const r=await fetch(PC_SITE_CLOUD_CONFIG.url+'/functions/v1/web-erp',{method:'POST',headers:{apikey:PC_SITE_CLOUD_CONFIG.key,Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({action,payload}),signal:ctl.signal});const out=await r.json();if(!r.ok||out.ok!==true)throw Error(out.error||'عملیات تأیید نشد؛ اطلاعات فرم را نگه دارید.');return out.data;}
  catch(e){if(e.name==='AbortError'||e instanceof TypeError)throw Error('پاسخ سرور نرسید. فرم حفظ شده؛ همان درخواست را دوباره بفرستید تا سند تکراری ایجاد نشود.');throw e;}
  finally{clearTimeout(timer);busy--;connection();}
 }
