 /* ── ویجت تصاویر کالا: پیش‌نمایش بالا، بارگذاری/نشانی، لیست با حذف پایین ── */
 const imgBox=o.querySelector('[data-images-box]');
 if(imgBox){
  const ta=o.querySelector('[name="images"]'),prev=imgBox.querySelector('[data-img-prev]'),list=imgBox.querySelector('[data-img-list]'),urlInp=imgBox.querySelector('[data-img-url]');
  const getImgs=()=>ta.value.split('\n').map(x=>x.trim()).filter(Boolean);
  const setImgs=arr=>{ta.value=arr.join('\n');draw();};
  const thumb=u=>{const v=window.PC_SITE_CLOUD?.webpImageUrl?window.PC_SITE_CLOUD.webpImageUrl(u):u;return /^(https?:|data:|\/)/.test(v||'')?v:'/images/academy-logo.webp';};
  const draw=()=>{
   const arr=getImgs();
   prev.innerHTML=arr.length?arr.map(u=>'<figure class="sh-imgthumb"><img src="'+E(thumb(u))+'" alt="" loading="lazy"></figure>').join(''):'<div class="sh-imgempty">هنوز تصویری نیست؛ از فایل بارگذاری کنید یا نشانی بدهید.</div>';
   list.innerHTML=arr.length?arr.map((u,i)=>'<div class="sh-imgrow"><span class="n">'+(i+1).toLocaleString('fa-IR')+'</span><img src="'+E(thumb(u))+'" alt="" loading="lazy"><span class="u" dir="ltr">'+E(u.length>60?u.slice(0,57)+'…':u)+'</span><button type="button" class="sh-btn danger sm" data-img-del="'+i+'" aria-label="حذف تصویر">حذف</button></div>').join(''):'';
   list.querySelectorAll('[data-img-del]').forEach(b=>b.onclick=()=>{const a=getImgs();a.splice(+b.dataset.imgDel,1);setImgs(a);const note=imgBox.querySelector('[data-img-note]');if(note)note.style.display='';});
  };
  const addImg=u=>{if(!u)return;const a=getImgs();if(a.includes(u)){toast('این تصویر قبلاً اضافه شده است.');return;}a.push(u);setImgs(a);const note=imgBox.querySelector('[data-img-note]');if(note)note.style.display='';};
  imgBox.querySelector('[data-img-add]').onclick=()=>{const u=urlInp.value.trim();if(!u)return;addImg(u);urlInp.value='';};
  /* عکس آپلودی اگر بزرگ بود خودکار فشرده‌تر می‌شود تا ذخیره به سقف حجم سرور نخورد */
  const budget=1400000;
  const addUploaded=u=>{
   if(!u)return Promise.resolve(false);
   const rest=budget-getImgs().join('').length;
   if(u.length<=rest){addImg(u);return Promise.resolve(true);}
   if(!window.PC_IMG||!window.PC_IMG.shrink){toast('حجم تصاویر زیاد است؛ عکس کمتر یا کوچک‌تر انتخاب کنید.',true);return Promise.resolve(false);}
   return window.PC_IMG.shrink(u,Math.max(180000,rest-20000)).then(small=>{
    if(small){addImg(small);toast('تصویر برای ذخیرهٔ مطمئن خودکار فشرده شد.');return true;}
    toast('حجم تصاویر زیاد است؛ یکی از عکس‌ها را حذف کنید تا جا شود.',true);return false;
   });
  };
  urlInp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();imgBox.querySelector('[data-img-add]').click();}});
  const upBtn=imgBox.querySelector('[data-upload-images]');
  upBtn.onclick=()=>{if(!window.PC_IMG){toast('ابزار بارگذاری تصویر آماده نیست؛ صفحه را تازه کنید.',true);return;}window.PC_IMG.pick(1400,u=>{addUploaded(u).then(ok=>{if(ok)toast('تصویر اضافه شد؛ برای اعمال، «ذخیره» پایین فرم را بزنید.');});});};
  draw();
 }
