 function staffForm(user=null){let current=user?.permissions||template('sales');const o=modal(user?'دسترسی کارمند':'افزودن کارمند فروشگاه','<form><div class="sh-form-grid">'+field('نام و نام خانوادگی','name',user?.name||'','text','required minlength="2"')+field('ایمیل ورود','email',user?.email||'','email','required dir="ltr" '+(user?'readonly':''))+select('واحد','department',[['manager','مدیر'],['sales','واحد فروش'],['purchasing','واحد خرید و انبار']],user?.department||'sales')+'<label class="sh-checkbox"><input type="checkbox" name="active" '+(user?.active!==false?'checked':'')+'> دسترسی فعال باشد</label></div><div class="sh-subhead">اختیار هر بخش — انتخاب مدیر</div><div data-permissions></div><div class="sh-alert" style="margin-top:14px">ثبت بدون ویرایش یعنی کارمند می‌تواند سند جدید ثبت کند، اما سند ذخیره‌شده را تغییر نمی‌دهد. اصلاح سند قطعی اجازهٔ جدا و کنترل وابستگی دارد.</div>'+formEnd(user?'ذخیره دسترسی‌ها':'ساخت حساب و رمز موقت'),true);const f=o.querySelector('form');const paint=()=>{o.querySelector('[data-permissions]').innerHTML=f.department.value==='manager'?'<p class="sh-note">مدیر عملیاتی به بخش‌های فروشگاه و مدیریت کارکنان دسترسی دارد. مدیریت محتوای سایت همچنان مخصوص مدیر اصلی وب است.</p>':'<div class="sh-table-wrap"><table class="sh-table sh-perm-table"><thead><tr><th>بخش</th><th>مشاهده</th><th>ثبت</th><th>ویرایش</th><th>برگشت</th></tr></thead><tbody>'+permissions.map(([key,label])=>'<tr><td>'+label+'</td>'+['view','create','edit','return'].map(action=>'<td>'+((key==='finance'&&['edit','return'].includes(action))||(['inventory','catalog'].includes(key)&&action==='return')?'—':'<input type="checkbox" data-perm="'+key+'.'+action+'" '+(current[key+'.'+action]?'checked':'')+' aria-label="'+label+' '+action+'">')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="sh-form-grid" style="margin-top:15px">'+[['reports.view','مشاهدهٔ گزارش‌های مالی و دفاتر'],['cost.view','مشاهدهٔ بهای خرید و ارزش انبار'],['sales.price','تغییر قیمت فروش و تخفیف'],['posted.correct','اصلاح/ابطال مستند فاکتور قطعی']].map(([k,t])=>'<label class="sh-checkbox"><input type="checkbox" data-perm="'+k+'" '+(current[k]?'checked':'')+'>'+t+'</label>').join('')+'</div>';};paint();f.department.onchange=()=>{current=template(f.department.value);paint();};submitForm(o,async()=>{const perms={};o.querySelectorAll('[data-perm]').forEach(i=>perms[i.dataset.perm]=i.checked);const payload={user_id:user?.user_id,name:f.elements.namedItem('name').value,email:f.email.value,department:f.department.value,active:f.active.checked,permissions:perms};const r=await api(user?'staff_save':'staff_create',payload);o.close();toast('دسترسی‌ها ذخیره شد');navigate('team');if(!user)credentials(r);});}
 function credentials(r){const o=modal('اطلاعات ورود خصوصی کارمند','<p class="sh-note">این رمز فقط همین بار نمایش داده می‌شود. آن را خصوصی به کارمند بدهید؛ در فاکتور یا دادهٔ عمومی ذخیره نشده است.</p><pre class="sh-credentials">'+E(r.email)+'\n'+E(r.password)+'</pre><p class="sh-note">ورود: صفحهٔ ورود مدیران، انتخاب پنل فروشگاه. کارمند بعد از ورود می‌تواند رمز را تغییر دهد.</p><div class="sh-actions">'+btn('کپی اطلاعات','copy-credentials')+'</div>');o.querySelector('[data-act]').onclick=()=>navigator.clipboard.writeText(r.email+'\n'+r.password).then(()=>toast('کپی شد')).catch(()=>toast('متن را انتخاب و کپی کنید',true));}
 async function statement(id){const r=await api('party_statement',{id});let ar=0,ap=0;const rows=r.rows.map(x=>{const v=N(x.debit)-N(x.credit);if(x.account==='1200')ar+=v;else ap-=v;return tr([D(x.doc_date),E(x.description),x.account==='1200'?'حساب مشتری':'حساب تأمین‌کننده',F(x.debit),F(x.credit)]);});modal('صورت‌حساب '+r.party.name,'<div class="sh-grid" style="grid-template-columns:1fr 1fr;margin-bottom:16px"><div class="sh-card"><span class="sh-note">مانده حساب مشتری</span><div class="sh-report-balance">'+F(ar)+'</div></div><div class="sh-card"><span class="sh-note">مانده حساب تأمین‌کننده</span><div class="sh-report-balance">'+F(ap)+'</div></div></div>'+table(['تاریخ','شرح','حساب','بدهکار','بستانکار'],rows)+'<p class="sh-note">طلب و بدهی جدا هستند؛ تهاتر خودکار انجام نمی‌شود. اعداد منفی، اعتبار طرف مقابل را نشان می‌دهند.</p>',true);}
