 async function ledger(account){const el=root.querySelector('#sh-view'),from=iso(el.querySelector('[name=from]').value),to=iso(el.querySelector('[name=to]').value);const r=await api('ledger',{account,from,to});let balance=N(r.opening);modal('دفتر حساب '+r.account.name,'<p class="sh-note">'+D(from)+' تا '+D(to)+' · مانده اول بازه: '+F(r.opening)+'</p>'+table(['تاریخ','شرح','بدهکار','بستانکار','مانده'],r.rows.map(x=>{balance+=N(x.debit)-N(x.credit);return tr([D(x.doc_date),E(x.description),F(x.debit),F(x.credit),F(balance)]);})),true);}
